// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // fuzz parameters: from address (as uint160), value v, decimals _decimals, and a boolean to choose failing callee
    function testFuzz_property(uint160 fromRaw, uint256 v, uint256 _decimals, bool calleeShouldRevert) public {
        // keep decimals in a reasonable range to avoid overflow in multiplication
        _decimals = bound(_decimals, 0, 18);
        // value v kept reasonable to avoid overflow when multiplied by 10**_decimals
        v = bound(v, 0, type(uint256).max / (10 ** _decimals + 1));

        address from = address(uint160(fromRaw));

        // require non-empty _tos as contract expects
        address[] memory tos = new address[](1);

        // deploy a helper that either reverts or succeeds based on calleeShouldRevert
        FailableReceiver helper = new FailableReceiver(calleeShouldRevert);
        tos[0] = address(helper);

        // call transfer and observe whether it reverts
        bool ok;
        try c.transfer(from, address(helper), tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (the single assertion):
        // The reference contract aborts the entire transfer (ok == false) when the callee reverts.
        // Therefore, for the chosen calleeShouldRevert == true, the reference must revert (ok == false).
        // The mutant that ignores the call's success flag may return true (ok == true) even when callee reverts.
        if (calleeShouldRevert) {
            assertTrue(!ok);
        } else {
            // when callee does NOT revert, both reference and mutant should succeed
            assertTrue(ok);
        }
    }
}

// Adversarial helper: when shouldRevert is true, the transferFrom call will revert; otherwise it records and succeeds.
contract FailableReceiver {
    bool public shouldRevert;
    // record last call arguments for completeness (not required by assertion but harmless)
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // match selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        if (shouldRevert) {
            revert("failing");
        }
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }
}
